import type { MultiSelectItemProps } from "../multi-select.types";
import type { AvatarProps } from "@components/avatar";

import React, { forwardRef, useEffect, useMemo, useRef } from "react";
import { Checkbox } from "@components/checkbox";
import { Menu } from "@components/menu";

import { MultiSelectClasses } from "../multi-select.styles";
import { useMultiSelect } from "../hooks/use-multi-select";

export const MultiSelectItem = forwardRef<HTMLDivElement, MultiSelectItemProps>(
  ({ children, value, ...props }, ref) => {
    const {
      pendingValue,
      onSingleValueChange,
      focusedValue,
      setFocusedValue,
      contentId,
      allOptions,
      handleSelectAll,
      isAllSelected,
      announcementFormatter,
      filteredOptions,
      setAnnouncement,
    } = useMultiSelect();

    const isSelectAllItem = value === "select-all";
    const isSelected = isSelectAllItem ? isAllSelected : pendingValue.includes(value);
    const isFocused = focusedValue === value;
    const itemRef = useRef<HTMLDivElement | null>(null);

    const option = useMemo(() => {
      const contextOption = allOptions.find((opt) => opt.value === value);
      // If option is not found in context (e.g. only children provided), create a fallback.
      // Ideally we would extract label from children, but for now safe fallback prevents crash.
      return contextOption || { label: "", value };
    }, [allOptions, value]);

    const disabled = option?.disabled;
    const itemId = `${contentId}-${value}`;

    useEffect(() => {
      if (isFocused) {
        itemRef.current?.scrollIntoView({ block: "nearest" });
        const announcement = announcementFormatter({
          option: option,
          index: filteredOptions.findIndex((opt) => opt.value === value),
          total: filteredOptions.length,
          isSelected: isSelected === true,
          isSelectAll: isSelectAllItem,
        });
        setAnnouncement(announcement);
      }
    }, [
      isFocused,
      announcementFormatter,
      option,
      filteredOptions,
      isSelected,
      isSelectAllItem,
      setAnnouncement,
      value,
    ]);

    // Handle children to ensure Avatar sizing and correct Checkbox placement
    const childrenArray = React.Children.toArray(children);
    const leadingIconIndex = childrenArray.findIndex(
      (child) =>
        React.isValidElement(child) &&
        (child.type as { displayName?: string }).displayName === Menu.ItemLeadingIcon.displayName,
    );

    let leadingIconContent: React.ReactNode = <Checkbox presentational checked={isSelected} />;
    let otherChildren = childrenArray;

    if (leadingIconIndex !== -1) {
      const existingLeadingIcon = childrenArray[leadingIconIndex];
      if (
        React.isValidElement<{ children?: React.ReactNode }>(existingLeadingIcon) &&
        existingLeadingIcon.props
      ) {
        leadingIconContent = (
          <>
            <Checkbox presentational checked={isSelected} />
            {existingLeadingIcon.props.children}
          </>
        );
      }
      // Remove the existing leading icon from the children list so we don't duplicate
      otherChildren = childrenArray.filter((_, index) => index !== leadingIconIndex);
    }

    const processedChildren = React.Children.map(otherChildren, (child) => {
      if (
        React.isValidElement<AvatarProps>(child) &&
        (child.type as { displayName?: string }).displayName === "Avatar"
      ) {
        return React.cloneElement(child, { ...child.props, size: "xsm" });
      }
      return child;
    });

    return (
      <Menu.Item
        ref={(node) => {
          if (typeof ref === "function") {
            ref(node);
          } else if (ref) {
            ref.current = node;
          }
          itemRef.current = node;
        }}
        aria-disabled={disabled}
        aria-selected={isSelected === true}
        className={MultiSelectClasses.item}
        data-highlighted={isFocused ? "" : undefined}
        id={itemId}
        role="option"
        tabIndex={0}
        onClick={(e) => {
          if (disabled) return;
          if (isSelectAllItem) {
            handleSelectAll?.(e);
          } else {
            onSingleValueChange(value);
          }
        }}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            if (disabled) return;
            if (isSelectAllItem) {
              handleSelectAll?.(e);
            } else {
              onSingleValueChange(value);
            }
            e.preventDefault();
          }
        }}
        onMouseOver={() => !disabled && setFocusedValue(value)}
        onPointerDown={(e) => e.preventDefault()}
        onPointerLeave={(e) => e.preventDefault()}
        onPointerMove={(e) => e.preventDefault()}
        onSelect={(e) => e.preventDefault()}
        {...props}
      >
        <Menu.ItemLeadingIcon>{leadingIconContent}</Menu.ItemLeadingIcon>
        {processedChildren}
      </Menu.Item>
    );
  },
);
MultiSelectItem.displayName = "MultiSelect.Item";
